package main

import (
	"strings"
	"unicode/utf8"

	"github.com/jterrazz/studio-station/src/catalog"
	"github.com/jterrazz/studio-station/src/disk"
)

const footprintPath = "docs/reference/footprint.md"

const footprintPreamble = `# Footprint

<!-- GENERATED by ` + "`make generate`" + ` from src/catalog: DO NOT EDIT -->

Everything ` + "`station`" + ` and the catalogue's apps write on a machine, by Disk group: what an erase would lose. The groups, the relocation rule and the commands that free, erase and move are [Disk](disk.md)'s.

` + "%LEVELS%" + `

Paths under ` + "`~/.config`, `~/.local/share`, `~/.local/state` and `~/.cache`" + ` follow their ` + "`XDG_*_HOME`" + ` variable when it is set and absolute. A path marked macOS lives on a Mac and a macOS VM; linux, on a Linux VM; vm, in every VM and never on a Mac; Mac, on a Mac only.`

func footprint() string {
	levels := table([]string{"Group", "Who removes it"}, [][]string{
		{"misplaced", "`station disk move <folder>` moves it where its app expects it, with no question"},
		{"can rebuild", "`station disk free`, with no question"},
		{"your data", "`station disk erase <app>`, its name typed"},
		{"never touched", "nobody: keys, tokens, settings and VM records; a setting's `off` where reversible"},
	})
	parts := []string{
		strings.Replace(footprintPreamble, "%LEVELS%", levels, 1),
		"## Station", table([]string{"Path", "Group", "Note"}, storedRows(catalog.StationDisk)), catalog.StationRetiredNote,
		"## Apps",
	}
	for _, t := range catalog.Apps {
		if !t.Disk.Declared() {
			continue
		}
		parts = append(parts, "### "+t.Name, table([]string{"Path", "Group", "Note"}, storedRows(t.Disk)))
		if lines := actionLines(t.Disk); lines != "" {
			parts = append(parts, lines)
		}
	}
	parts = append(parts,
		"## Settings", table([]string{"Setting", "Path", "Group", "Note"}, settingsRows()),
		"## Home-root exceptions", "What an app keeps at the root of the home folder, declared with its reason; anything else there is misplaced.", table([]string{"Path", "Reason"}, exceptionRows()),
		"## Relocations", "Written by `station init` into the app's own file, never by a shell variable.", table([]string{"App", "File", "Key", "Value", "Status"}, relocationRows()),
	)
	return strings.Join(parts, "\n\n") + "\n"
}

func shown(pattern string) string {
	for prefix, root := range map[string]string{"{config}": "~/.config", "{data}": "~/.local/share", "{state}": "~/.local/state", "{cache}": "~/.cache"} {
		if rest, ok := strings.CutPrefix(pattern, prefix); ok {
			return root + rest
		}
	}
	return pattern
}

// value: a path's Disk group in the owner's words; no level is Misplaced,
// a folder where its app's own settings moved it from.
func group(l catalog.Level) string {
	if l == "" {
		return strings.ReplaceAll(string(disk.Misplaced), "-", " ")
	}
	return strings.ReplaceAll(string(disk.GroupOf(l)), "-", " ")
}

func code(s string) string { return "`" + s + "`" }

func on(kinds []catalog.MachineKind) string {
	has := map[catalog.MachineKind]bool{}
	for _, k := range kinds {
		has[k] = true
	}
	switch {
	case len(has) == 0 || len(has) == 3:
		return ""
	case len(has) == 2 && has[catalog.Mac] && has[catalog.MacOS]:
		return "macOS"
	case len(has) == 2 && has[catalog.Linux] && has[catalog.MacOS]:
		return "vm"
	case len(has) == 1 && has[catalog.Linux]:
		return "linux"
	case len(has) == 1 && has[catalog.Mac]:
		return "Mac"
	case len(has) == 1 && has[catalog.MacOS]:
		return "macOS VM"
	}
	return "Mac and Linux VM"
}

func note(parts ...string) string {
	var kept []string
	for _, p := range parts {
		if p != "" {
			kept = append(kept, p)
		}
	}
	return strings.Join(kept, "; ")
}

func memoNote(memos []string) string {
	if len(memos) == 0 {
		return ""
	}
	shownMemos := make([]string, 0, len(memos))
	for _, m := range memos {
		shownMemos = append(shownMemos, code(m))
	}
	return strings.Join(shownMemos, ", ") + " rewritten on every call, not counted"
}

func storedRows(s catalog.Disk) [][]string {
	rows := make([][]string, 0, len(s.Paths)+len(s.Installed)+len(s.Misplaced))
	for _, p := range s.Paths {
		rows = append(rows, []string{code(shown(p.Path)), group(p.Level), note(on(p.On), p.Note, memoNote(p.Memos))})
	}
	for _, p := range s.Installed {
		removal := s.Removal[p]
		if removal == "" {
			removal = "removed by `station apps remove`"
		}
		rows = append(rows, []string{code(shown(p)), "installed", removal})
	}
	for _, st := range s.Misplaced {
		moves := make([]string, 0, len(st.Move))
		for _, m := range st.Move {
			moves = append(moves, code(shown(m.From))+" to "+code(shown(m.To)))
		}
		detail := "`station disk free` empties it"
		if len(moves) > 0 {
			detail = "`station disk move " + st.Path + "` moves " + strings.Join(moves, ", ")
		}
		rows = append(rows, []string{code(st.Path), group(""), detail})
	}
	return rows
}

func actionLines(s catalog.Disk) string {
	var lines []string
	if c := actions(s.Free); c != "" {
		lines = append(lines, "Free: "+c+".")
	}
	if r := actions(s.Erase); r != "" {
		lines = append(lines, "Erase: "+r+".")
	} else if s.NoErase != "" {
		lines = append(lines, "Erase: none ("+s.NoErase+").")
	}
	if s.Quit != "" {
		lines = append(lines, "An erase refuses while "+code(s.Quit)+" runs.")
	}
	return strings.Join(lines, " ")
}

func actions(list []catalog.Action) string {
	var out []string
	for _, a := range list {
		if len(a.Run) > 0 {
			run := code(strings.Join(a.Run, " "))
			if a.Exists != "" {
				run += " when " + code(shown(a.Exists)) + " exists"
			}
			out = append(out, run)
		}
		for _, d := range a.Delete {
			out = append(out, "delete "+code(shown(d)))
		}
	}
	return strings.Join(out, ", ")
}

func settingsRows() [][]string {
	var rows [][]string
	for _, it := range catalog.Settings {
		writes := it.Writes
		if d, ok := it.Effect.(catalog.Dotfiles); ok {
			for _, c := range d.Files {
				writes = append(writes, catalog.Stored{Path: c.To, Level: catalog.LevelSettings, Note: "the embedded " + code(c.From)})
			}
		}
		if t, ok := it.Effect.(catalog.Touch); ok && len(writes) == 0 {
			writes = append(writes, catalog.Stored{Path: t.Path, Level: catalog.LevelSettings})
		}
		for _, w := range writes {
			rows = append(rows, []string{it.Name, code(shown(w.Path)), group(w.Level), w.Note})
		}
	}
	return rows
}

func exceptionRows() [][]string {
	rows := make([][]string, 0, len(catalog.HomeExceptions))
	for _, e := range catalog.HomeExceptions {
		rows = append(rows, []string{code("~/" + e.Path), e.Reason})
	}
	return rows
}

func relocationRows() [][]string {
	var rows [][]string
	for _, t := range catalog.Apps {
		for _, r := range t.Disk.Relocate {
			status := "written"
			if r.Pending != "" {
				status = "pending: " + r.Pending
			}
			rows = append(rows, []string{t.Name, string(r.File), code(r.Key), code(shown(r.Value)), status})
		}
	}
	return rows
}

func table(header []string, rows [][]string) string {
	all := append([][]string{header}, rows...)
	widths := make([]int, len(header))
	for _, row := range all {
		for i, cell := range row {
			widths[i] = max(widths[i], utf8.RuneCountInString(cell), 3)
		}
	}
	lines := make([]string, 0, len(all)+1)
	for i, row := range all {
		cells := make([]string, len(row))
		for j, cell := range row {
			cells[j] = pad(cell, widths[j])
		}
		lines = append(lines, "| "+strings.Join(cells, " | ")+" |")
		if i == 0 {
			dashes := make([]string, len(header))
			for j := range header {
				dashes[j] = strings.Repeat("-", widths[j])
			}
			lines = append(lines, "| "+strings.Join(dashes, " | ")+" |")
		}
	}
	return strings.Join(lines, "\n")
}
